//! `CONFIG REWRITE`: writes the settings in effect back to the configuration
//! file the server was started with, the way Redis does.
//!
//! The file keeps its comments, its order and the lines this server does
//! not know. A setting already in the file is rewritten where it is, even
//! at its default; one that is not is added only if it differs from the
//! default, after a `# Generated by CONFIG REWRITE` line at the end. Lines
//! left over (a `save` line too many, say) are blanked, and `user` lines
//! are always written, since users made with `ACL SETUSER` exist nowhere
//! else.
//!
//! Text values are written as the starter file writes them, bare or in
//! single quotes when that is safe, rather than always in double quotes as
//! Redis does: a Windows path stays readable instead of having every
//! backslash doubled. Redis reads both.

use std::collections::HashMap;
use std::fs;
use std::io::{self, Write};
use std::path::Path;

use crate::Server;

/// The line that comes before the settings this command adds.
const MARKER: &str = "# Generated by CONFIG REWRITE";

/// How a setting's value is written.
#[derive(Clone, Copy)]
enum Kind {
    /// As it is: a number, a name, `yes` or `no`.
    Plain,
    /// Text that may need quotes: a path, a password.
    Text,
    /// A number of bytes, as `64mb` where it is a whole number of them.
    Bytes,
}

/// The settings written back, in the order new ones are added, with their
/// defaults as `CONFIG GET` shows them. Settings `CONFIG GET` lists that
/// describe fixed behaviour (`hz`, the listpack sizes) are left as they
/// are in the file, as is `rdb-key-save-delay`, a test aid.
const SETTINGS: &[(&str, Kind, &str)] = &[
    ("bind", Kind::Plain, "127.0.0.1"),
    ("port", Kind::Plain, "6379"),
    ("databases", Kind::Plain, "16"),
    ("maxclients", Kind::Plain, "10000"),
    ("slowlog-log-slower-than", Kind::Plain, "10000"),
    ("slowlog-max-len", Kind::Plain, "128"),
    ("dir", Kind::Text, "."),
    ("dbfilename", Kind::Text, "dump.rdb"),
    ("busy-reply-threshold", Kind::Plain, "5000"),
    ("maxmemory", Kind::Bytes, "0"),
    ("maxmemory-policy", Kind::Plain, "noeviction"),
    ("maxmemory-samples", Kind::Plain, "5"),
    ("lfu-log-factor", Kind::Plain, "10"),
    ("lfu-decay-time", Kind::Plain, "1"),
    ("appendonly", Kind::Plain, "no"),
    ("appendfsync", Kind::Plain, "everysec"),
    ("appenddirname", Kind::Text, "appendonlydir"),
    ("appendfilename", Kind::Text, "appendonly.aof"),
    ("auto-aof-rewrite-percentage", Kind::Plain, "100"),
    ("auto-aof-rewrite-min-size", Kind::Bytes, "67108864"),
    ("aof-load-truncated", Kind::Plain, "yes"),
    ("save", Kind::Plain, "3600 1 300 100 60 10000"),
    ("requirepass", Kind::Text, ""),
    ("protected-mode", Kind::Plain, "yes"),
    ("enable-debug-command", Kind::Plain, "no"),
    ("notify-keyspace-events", Kind::Text, ""),
];

/// Older names a file may use for a setting.
fn canonical(name: &str) -> &str {
    match name {
        "lua-time-limit" => "busy-reply-threshold",
        other => other,
    }
}

/// Rewrites the configuration file. `value` gives a setting's value as
/// `CONFIG GET` shows it.
pub(crate) fn rewrite(server: &Server, value: impl Fn(&str) -> String) -> io::Result<()> {
    let Some(path) = server.config_file.as_deref() else {
        return Err(io::Error::other(
            "The server is running without a config file",
        ));
    };
    let path = Path::new(path);
    // A file deleted since start-up is written afresh.
    let text = match fs::read_to_string(path) {
        Ok(text) => text,
        Err(e) if e.kind() == io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(e),
    };
    let mut wanted: Vec<(&str, Vec<String>, bool)> = SETTINGS
        .iter()
        .map(|&(name, kind, default)| {
            let current = value(name);
            let changed = current != default;
            (name, lines(name, kind, &current), changed)
        })
        .collect();
    wanted.push(("user", server.acl.config_lines(), true));
    let updated = apply(&text, &wanted);
    write_replacing(path, &updated)
}

/// The lines that set `name` to `value`.
fn lines(name: &str, kind: Kind, value: &str) -> Vec<String> {
    if name == "save" {
        let numbers: Vec<&str> = value.split_whitespace().collect();
        if numbers.is_empty() {
            return vec!["save \"\"".to_owned()];
        }
        return numbers
            .chunks(2)
            .map(|pair| format!("save {}", pair.join(" ")))
            .collect();
    }
    let value = match kind {
        Kind::Plain => value.to_owned(),
        Kind::Text => quote(value),
        Kind::Bytes => value.parse().map_or_else(|_| value.to_owned(), bytes),
    };
    vec![format!("{name} {value}")]
}

/// `text` with the settings in `wanted` written in.
fn apply(text: &str, wanted: &[(&str, Vec<String>, bool)]) -> String {
    let crlf = text.contains("\r\n");
    let mut lines: Vec<String> = text.lines().map(str::to_owned).collect();
    let mut found: HashMap<String, Vec<usize>> = HashMap::new();
    let mut marked = false;
    for (index, line) in lines.iter().enumerate() {
        let line = line.trim();
        if line == MARKER {
            marked = true;
        }
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let name = line
            .split_whitespace()
            .next()
            .unwrap_or_default()
            .to_ascii_lowercase();
        found
            .entry(canonical(&name).to_owned())
            .or_default()
            .push(index);
    }

    let mut added = Vec::new();
    for (name, new, changed) in wanted {
        let old = found.remove(*name).unwrap_or_default();
        if old.is_empty() && !changed {
            continue;
        }
        let mut new = new.iter().cloned();
        for index in old {
            lines[index] = new.next().unwrap_or_default();
        }
        added.extend(new);
    }
    if !added.is_empty() {
        if !marked {
            if lines.last().is_some_and(|line| !line.trim().is_empty()) {
                lines.push(String::new());
            }
            lines.push(MARKER.to_owned());
        }
        lines.extend(added);
    }

    let newline = if crlf { "\r\n" } else { "\n" };
    let mut out = lines.join(newline);
    out.push_str(newline);
    out
}

/// Replaces the file in one step, so that a crash part-way leaves the old
/// one, never half of the new one.
fn write_replacing(path: &Path, text: &str) -> io::Result<()> {
    let mut temporary = path.as_os_str().to_owned();
    temporary.push(".rewrite.tmp");
    let temporary = Path::new(&temporary);
    let written = fs::File::create(temporary).and_then(|mut file| {
        file.write_all(text.as_bytes())?;
        file.sync_all()
    });
    match written.and_then(|()| fs::rename(temporary, path)) {
        Ok(()) => Ok(()),
        Err(e) => {
            let _ = fs::remove_file(temporary);
            Err(e)
        }
    }
}

/// A number of bytes as Redis writes it: `2gb`, `64mb`, `1kb`, or bytes.
fn bytes(n: u64) -> String {
    const KB: u64 = 1024;
    const MB: u64 = KB * 1024;
    const GB: u64 = MB * 1024;
    match n {
        0 => "0".to_owned(),
        n if n % GB == 0 => format!("{}gb", n / GB),
        n if n % MB == 0 => format!("{}mb", n / MB),
        n if n % KB == 0 => format!("{}kb", n / KB),
        n => n.to_string(),
    }
}

/// One value as a configuration file takes it: bare where that is safe,
/// otherwise in single quotes, which are literal, or in double quotes with
/// escapes when the value itself holds a single quote.
pub fn quote(value: &str) -> String {
    let bare = !value.is_empty()
        && !value.starts_with('#')
        && !value.contains(|c: char| c.is_whitespace() || c == '"' || c == '\'');
    if bare {
        value.to_owned()
    } else if !value.contains('\'') && !value.contains(['\n', '\r']) {
        format!("'{value}'")
    } else {
        let mut out = String::from("\"");
        for c in value.chars() {
            match c {
                '\\' | '"' => out.extend(['\\', c]),
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                c => out.push(c),
            }
        }
        out.push('"');
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn wanted(
        settings: &[(&'static str, &[&str], bool)],
    ) -> Vec<(&'static str, Vec<String>, bool)> {
        settings
            .iter()
            .map(|(name, lines, changed)| {
                (
                    *name,
                    lines.iter().map(|line| (*line).to_owned()).collect(),
                    *changed,
                )
            })
            .collect()
    }

    #[test]
    fn settings_are_rewritten_in_place_and_new_ones_added_at_the_end() {
        let text = "# My settings\nport 6379\n\n# saving\nsave 900 1\nsave 300 10\n\
                    maxmemory 100mb\nlua-time-limit 4000\nslowlog-max-len 128\nloglevel notice\n";
        let out = apply(
            text,
            &wanted(&[
                ("port", &["port 6379"], false),
                ("slowlog-max-len", &["slowlog-max-len 128"], false),
                ("maxclients", &["maxclients 500"], true),
                ("maxmemory-samples", &["maxmemory-samples 5"], false),
                ("busy-reply-threshold", &["busy-reply-threshold 7000"], true),
                ("maxmemory", &["maxmemory 2gb"], true),
                ("save", &["save 60 5"], true),
                (
                    "user",
                    &["user default on nopass sanitize-payload ~* &* +@all"],
                    true,
                ),
            ]),
        );
        // As Redis 7.4 wrote the same file, but for the order of the
        // settings it adds, which in Redis is that of a hash table.
        assert_eq!(
            out,
            "# My settings\nport 6379\n\n# saving\nsave 60 5\n\nmaxmemory 2gb\n\
             busy-reply-threshold 7000\nslowlog-max-len 128\nloglevel notice\n\
             \n# Generated by CONFIG REWRITE\nmaxclients 500\n\
             user default on nopass sanitize-payload ~* &* +@all\n"
        );
        // A second rewrite adds below the line already there.
        let again = apply(
            &out,
            &wanted(&[
                ("maxclients", &["maxclients 500"], true),
                ("save", &["save 60 5", "save 10 1"], true),
            ]),
        );
        assert!(
            again.ends_with("# Generated by CONFIG REWRITE\nmaxclients 500\nuser default on nopass sanitize-payload ~* &* +@all\nsave 10 1\n"),
            "{again}"
        );
        assert_eq!(again.matches(MARKER).count(), 1);
    }

    #[test]
    fn an_empty_file_gets_only_what_differs() {
        let out = apply(
            "",
            &wanted(&[("port", &["port 6379"], false), ("port2", &["x 1"], true)]),
        );
        assert_eq!(out, "# Generated by CONFIG REWRITE\nx 1\n");
    }

    #[test]
    fn windows_line_endings_are_kept() {
        let out = apply(
            "port 1\r\n# note\r\n",
            &wanted(&[("port", &["port 2"], true)]),
        );
        assert_eq!(out, "port 2\r\n# note\r\n");
    }

    #[test]
    fn values_are_written_as_redis_reads_them() {
        assert_eq!(bytes(0), "0");
        assert_eq!(bytes(1536), "1536");
        assert_eq!(bytes(3 << 20), "3mb");
        assert_eq!(bytes(2 << 30), "2gb");
        assert_eq!(bytes(4096), "4kb");
        assert_eq!(lines("save", Kind::Plain, ""), ["save \"\""]);
        assert_eq!(
            lines("save", Kind::Plain, "3600 1 300 100"),
            ["save 3600 1", "save 300 100"]
        );
        assert_eq!(
            lines("dir", Kind::Text, r"C:\ProgramData\Rexyra\data"),
            [r"dir C:\ProgramData\Rexyra\data"]
        );
        assert_eq!(
            lines("dir", Kind::Text, r"D:\My Data"),
            [r"dir 'D:\My Data'"]
        );
        assert_eq!(lines("requirepass", Kind::Text, ""), ["requirepass ''"]);
        assert_eq!(
            lines("requirepass", Kind::Text, "it's \"x\"\\"),
            [r#"requirepass "it's \"x\"\\""#]
        );
        assert_eq!(
            lines("maxmemory", Kind::Bytes, "1073741824"),
            ["maxmemory 1gb"]
        );
    }
}
